import{_ as t,o as s,c as i,a0 as a}from"./chunks/framework.DVUHX04-.js";const n="/pi-extensions/assets/sync-view.CapIdspz.png",o="/pi-extensions/assets/sync-status.P6CIaxwD.png",y=JSON.parse('{"title":"sync extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/sync/index.md","filePath":"extensions/sync/index.md","lastUpdated":1789775493000}'),d={name:"extensions/sync/index.md"};function r(h,e,c,l,p,g){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="sync-extension" tabindex="-1">sync extension <a class="header-anchor" href="#sync-extension" aria-label="Permalink to &quot;sync extension&quot;">​</a></h1><p>Keeps the user&#39;s pi config (the files named in a default-deny sync manifest) in sync across devices through a pluggable Backend. v1 ships exactly one backend: a <strong>secret GitHub Gist</strong>. The Backend is a single seam, so a later backend (S3, Syncthing, rsync) is a new implementation, not a redesign. <code>push</code> and <code>pull</code> run a three-way merge (the device&#39;s last-synced base, local, remote); a same-second conflict keeps the local side, and every overwritten file gets a <code>&lt;path&gt;.&lt;millis&gt;.bak</code> backup. <code>push</code> uploads the merged tree before it touches the local tree, so a network failure leaves the tree intact.</p><p><a href="/pi-extensions/extensions/sync/internals.html">Internals</a>: the manifest, the merge semantics, the token lifecycle, and the Gist backend reference.</p><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><p>The <code>/sync status</code> view in the TUI, with the device in sync:</p><p><img src="'+n+'" alt="sync status view"></p><p>The same status from the <code>pi-sync status</code> CLI:</p><p><img src="'+o+`" alt="pi-sync status CLI"></p><h2 id="onboarding-one-command-per-device" tabindex="-1">Onboarding (one command per device) <a class="header-anchor" href="#onboarding-one-command-per-device" aria-label="Permalink to &quot;Onboarding (one command per device)&quot;">​</a></h2><p>The whole setup is a guided wizard. Each human action is either one browser page or one key press.</p><p><strong>Once per account (the only account-level step):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/setup-sync-wizard.sh</span></span></code></pre></div><p>The bash wizard opens the GitHub OAuth app page, walks the form (name, a <code>http://127.0.0.1</code> callback URL that is never used, the <strong>Use expiring tokens</strong> checkbox that ADR 0007 needs, and the <strong>device flow opt-in</strong> box that GitHub now requires on every app), and stores the public <strong>client id</strong> in <code>&lt;state-dir&gt;/oauth-client.json</code>. Before it stores the id it verifies it against GitHub: a live id gets a throwaway device code, a typo is caught on the spot, and an app that left the device flow off is named by GitHub&#39;s own <code>device_flow_disabled</code> refusal - the wizard opens the settings page where the opt-in box lives (offline or without <code>curl</code> the check degrades to a warning and a confirm). A client secret is never created or stored: the device flow does not use one. Scripted contexts can set <code>PI_SYNC_OAUTH_CLIENT_ID</code> instead.</p><p><strong>On each device:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi-sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # first device: create the shared secret gist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi-sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gist-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # every later device: join that gist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi-sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # upload this device&#39;s changes (merged)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi-sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # take the other devices&#39; changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi-sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # ahead / behind / conflict, no side effects</span></span></code></pre></div><p>What <code>init</code> does, step by step:</p><ol><li><strong>Auth.</strong> With no token on the device, the CLI runs the GitHub <strong>OAuth device flow</strong> (ADR 0007): it prints a short code and the verification URL (<code>github.com/login/device</code>), and polls. You open the URL in a browser and enter the code; the token it stores carries only the <code>gist</code> scope. On expiry or denial it offers exactly one fresh retry, or cancels. It never fails silently and never retries without you.</li><li><strong>Preview.</strong> Before anything is written, the wizard prints the preview: which files are in scope, which files would be sent or replaced, and which files would arrive. The gist is created, and a device joins, only after you confirm with <code>y</code>. Declining writes nothing (the stored token excepted, if the flow already finished).</li><li><strong>Report.</strong> The create path prints the gist id and the exact join command for the other devices. The join path prints the files it adopted.</li></ol><p>In pi, the same wizard runs as <code>/sync init [gist-id]</code>: the device flow is a TUI dialog, and the preview confirm is a TUI dialog.</p><h3 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--yes</code></td><td>Confirm the preview without prompting; the preview is still shown. Non-tty runs (CI, scripts) need this.</td></tr><tr><td><code>--force</code></td><td>Re-init an already-joined device without prompting. The shared tree re-adopts; the local manifest keeps its gist id.</td></tr></tbody></table><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><p>All five exist as pi commands (<code>/sync ...</code>, with a TUI status dialog) and as CLI verbs (same code, <code>extensions/sync/ops.ts</code>):</p><table tabindex="0"><thead><tr><th>Verb</th><th>Effect</th></tr></thead><tbody><tr><td><code>pi-sync init</code> (no id)</td><td>The create path: on auth, preview, and confirm, it creates the shared secret gist from this device&#39;s tree.</td></tr><tr><td><code>pi-sync init &lt;gist-id&gt;</code></td><td>The join path: on auth, preview, and confirm, this device adopts the shared tree and records the gist id. On an already-joined device it re-adopts like a pull (the preview lists what will be replaced; local edits are kept) and confirms again; <code>--force</code> skips the confirm.</td></tr><tr><td><code>pi-sync push</code></td><td>Merge local + remote, upload the merged tree, then apply the merge to the local tree. On a device that never ran <code>init</code>, push is a plain error pointing at <code>pi-sync init</code>: it never creates.</td></tr><tr><td><code>pi-sync pull</code></td><td>Merge local + remote and apply to the local tree.</td></tr><tr><td><code>pi-sync status</code></td><td>The merge without side effects: ahead / behind / conflict.</td></tr></tbody></table><p><code>push</code> uploads <strong>first</strong>: a network failure leaves the local tree untouched. Unreadable files and non-text files are skipped with a warning line in the report, so a partial or binary-laden tree never silently goes out wrong. The device-local base is recorded only after the local apply succeeds, so a push whose apply fails cannot leave a half-merged tree labeled &quot;in sync&quot;.</p><h2 id="in-a-pi-session" tabindex="-1">In a pi session <a class="header-anchor" href="#in-a-pi-session" aria-label="Permalink to &quot;In a pi session&quot;">​</a></h2><p><code>/sync init [gist-id]</code>, <code>/sync push</code>, <code>/sync pull</code>, and <code>/sync status</code> open a TUI dialog with the full report (in print and RPC modes the report goes to the stream); <code>/sync</code> alone prints the usage. <code>/sync init</code> runs the same wizard as the CLI: the device flow as a TUI dialog (it only starts in the TUI, never in print or RPC modes), the preview confirm as a dialog.</p><p>On session start, a joined device gets a footer line with the ahead/behind counts when the tree has moved:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sync: ↑2 ↓1</span></span></code></pre></div><p>A green up-arrow plus count when ahead, a red down-arrow plus count when behind, both when the device drifts both ways. The line sits on the right of the shared footer status line (see <code>shared/status-line.ts</code>), in the column above the provider and model.</p><p>When a token exists but this device has not joined a gist yet, the line nudges instead of staying empty:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sync: not joined - run /sync init</span></span></code></pre></div><p>No token, zero drift, or a failed read: the line stays empty. The probe only reports - it never starts a re-authentication or device flow - and nothing on startup ever mutates the tree or the backend.</p>`,32)])])}const k=t(d,[["render",r]]);export{y as __pageData,k as default};
